-- DB17: Owner-only Fee & Finance phase 1: categories and class fee plans.
-- No bills, receipts, discounts or balances are generated by configuration.
-- Money is integer minor currency units; plan versioning preserves history.
create table if not exists app_private.sms_fee_setup_audit (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id),
  campus_id uuid references public.campuses(id),
  actor_id uuid not null references auth.users(id),
  action text not null check (action in ('category_created','plan_activated')),
  object_id uuid not null,
  detail jsonb not null default '{}'::jsonb,
  happened_at timestamptz not null default now()
);
alter table app_private.sms_fee_setup_audit enable row level security;
revoke all on app_private.sms_fee_setup_audit from public,anon,authenticated;

create or replace function app_private.owner_fee_setup_snapshot(
  p_school uuid,p_campus uuid,p_year uuid
) returns jsonb language plpgsql stable security definer set search_path=''
as $fn$
declare v_school public.schools%rowtype;
v_year public.academic_years%rowtype;
v_categories jsonb;
v_classes jsonb;
begin
 if not app_private.is_verified_school_owner((select auth.uid()),p_school)
 or not exists(select 1 from public.campuses c where c.id=p_campus
   and c.school_id=p_school and c.is_active)
 then raise exception 'Only verified Owner can view this campus fee setup'
   using errcode='42501'; end if;
 select * into v_school from public.schools where id=p_school;
 select * into v_year from public.academic_years
 where id=p_year and school_id=p_school;
 if v_year.id is null then raise exception 'Academic year not in school'
   using errcode='42501';end if;

 select coalesce(jsonb_agg(jsonb_build_object(
   'id',c.id,'code',c.code,'name',c.name,'frequency',c.charge_frequency,
   'discountable',c.is_discountable,'active',c.is_active)
   order by c.name,c.code),'[]'::jsonb)
 into v_categories from public.fee_categories c where c.school_id=p_school;

 select coalesce(jsonb_agg(jsonb_build_object(
   'id',c.id,'name',c.name,'sort_order',c.sort_order,
   'plan',case when p.id is null then null else
     jsonb_build_object('id',p.id,'name',p.name,'version',p.version_no,
       'status',p.status,'effective_from',p.effective_from,
       'items',coalesce((
         select jsonb_agg(jsonb_build_object(
           'category_id',i.category_id,'amount_minor',i.amount_minor,
           'optional',i.is_optional) order by i.category_id)
         from public.fee_plan_items i where i.fee_plan_id=p.id
       ),'[]'::jsonb))
     end
   ) order by c.sort_order,c.name),'[]'::jsonb)
 into v_classes
 from public.classes c
 left join lateral (
   select fp.* from public.fee_plans fp
   where fp.school_id=p_school and fp.campus_id=p_campus
     and fp.academic_year_id=p_year and fp.class_id=c.id
     and fp.status='active'
   order by fp.version_no desc limit 1
 ) p on true
 where c.school_id=p_school and c.campus_id=p_campus
   and c.academic_year_id=p_year;
 return jsonb_build_object(
   'school_id',p_school,'campus_id',p_campus,'year_id',p_year,
   'year_label',v_year.label,'currency',v_school.currency_code,
   'categories',v_categories,'classes',v_classes);
end;
$fn$;
create or replace function public.owner_fee_setup_snapshot(
 p_school uuid,p_campus uuid,p_year uuid
) returns jsonb language sql stable security invoker set search_path=''
as $fn$ select app_private.owner_fee_setup_snapshot(p_school,p_campus,p_year); $fn$;

create or replace function app_private.owner_create_fee_category(
 p_school uuid,p_code text,p_name text,p_frequency text,p_discountable boolean
) returns jsonb language plpgsql security definer set search_path=''
as $fn$
declare v_id uuid;v_actor uuid:=(select auth.uid());
begin
 if not app_private.is_verified_school_owner(v_actor,p_school)
 then raise exception 'Only verified Owner can configure fee categories'
   using errcode='42501';end if;
 if p_code is null or p_code !~ '^[A-Z][A-Z0-9_]{1,29}$'
 or length(btrim(coalesce(p_name,''))) not between 2 and 120
 or p_frequency not in ('monthly','one_time','manual')
 or p_discountable is null
 then raise exception 'Invalid fee category inputs'
   using errcode='22023';end if;
 insert into public.fee_categories(school_id,code,name,charge_frequency,is_discountable,is_active)
 values(p_school,p_code,btrim(p_name),p_frequency,p_discountable,true)
 returning id into v_id;
 insert into app_private.sms_fee_setup_audit(
 school_id,actor_id,action,object_id,detail)
 values(p_school,v_actor,'category_created',v_id,
   jsonb_build_object('code',p_code,'frequency',p_frequency));
 return jsonb_build_object('id',v_id,'code',p_code,'saved',true);
end;
$fn$;
create or replace function public.owner_create_fee_category(
 p_school uuid,p_code text,p_name text,p_frequency text,p_discountable boolean
) returns jsonb language sql security invoker set search_path=''
as $fn$ select app_private.owner_create_fee_category(
 p_school,p_code,p_name,p_frequency,p_discountable); $fn$;

create or replace function app_private.owner_save_class_fee_plan(
 p_school uuid,p_campus uuid,p_year uuid,p_class uuid,
 p_name text,p_items jsonb
) returns jsonb language plpgsql security definer set search_path=''
as $fn$
declare v_actor uuid:=(select auth.uid());v_version int;v_id uuid;
v_date date;v_year public.academic_years%rowtype;v_rows int;v_it jsonb;
v_seen uuid[]:='{}'::uuid[];v_category uuid;v_amount bigint;
begin
 if not app_private.is_verified_school_owner(v_actor,p_school)
 then raise exception 'Only verified Owner can save school fee plans'
   using errcode='42501';end if;
 if length(btrim(coalesce(p_name,''))) not between 2 and 120
   or p_items is null or jsonb_typeof(p_items)<>'array'
   or jsonb_array_length(p_items) not between 1 and 30
 then raise exception 'Plan name and at least one category amount are required'
   using errcode='22023';end if;
 select * into v_year from public.academic_years
 where id=p_year and school_id=p_school and is_active;
 if v_year.id is null then raise exception 'Active academic year required'
   using errcode='42501';end if;
 v_date:=greatest(current_date,v_year.starts_on);
 if v_date>v_year.ends_on then
   raise exception 'Academic year has ended' using errcode='22023';
 end if;

 -- Lock parent to serialize versions for this class; do not lock whole school.
 perform 1 from public.classes c join public.campuses camp
   on camp.id=c.campus_id and camp.school_id=c.school_id and camp.is_active
 where c.id=p_class and c.campus_id=p_campus
   and c.school_id=p_school and c.academic_year_id=p_year for update of c;
 if not found then raise exception 'Class is not in authorized campus/year'
   using errcode='42501';end if;

 for v_it in select value from jsonb_array_elements(p_items) loop
   if jsonb_typeof(v_it)<>'object'
   or (v_it->>'category_id') is null
   or (v_it->>'amount_minor') is null
   or (v_it->>'amount_minor') !~ '^[0-9]{1,12}$'
   or jsonb_typeof(v_it->'optional') not in ('boolean')
   then raise exception 'Invalid fee item'
     using errcode='22023';end if;
   v_category:=(v_it->>'category_id')::uuid;
   v_amount:=(v_it->>'amount_minor')::bigint;
   if v_category=any(v_seen) or v_amount>100000000000 then
     raise exception 'Duplicate category or excessive fee amount'
       using errcode='22023';end if;
   if not exists(select 1 from public.fee_categories fc
       where fc.id=v_category and fc.school_id=p_school and fc.is_active)
   then raise exception 'Fee category not active in school'
     using errcode='42501';end if;
   v_seen:=array_append(v_seen,v_category);
 end loop;

 select coalesce(max(version_no),0)+1 into v_version
 from public.fee_plans where school_id=p_school and campus_id=p_campus
   and academic_year_id=p_year and class_id=p_class;
 -- Retire previous active configuration; never delete historical versions.
 update public.fee_plans
 set status='retired',
     effective_to=case when effective_from<v_date then v_date-1
                      else effective_to end
 where school_id=p_school and campus_id=p_campus
   and academic_year_id=p_year and class_id=p_class and status='active';

 insert into public.fee_plans(
 school_id,campus_id,academic_year_id,class_id,name,version_no,
 effective_from,status,created_by)
 values(p_school,p_campus,p_year,p_class,btrim(p_name),v_version,
   v_date,'active',v_actor) returning id into v_id;

 insert into public.fee_plan_items(
   school_id,campus_id,fee_plan_id,category_id,amount_minor,is_optional)
 select p_school,p_campus,v_id,
   (i.value->>'category_id')::uuid,
   (i.value->>'amount_minor')::bigint,
   (i.value->>'optional')::boolean
 from jsonb_array_elements(p_items) i(value);
 get diagnostics v_rows=row_count;
 if v_rows<>jsonb_array_length(p_items) then
   raise exception 'Fee items were not fully saved'
     using errcode='23514';end if;

 insert into app_private.sms_fee_setup_audit(
 school_id,campus_id,actor_id,action,object_id,detail)
 values(p_school,p_campus,v_actor,'plan_activated',v_id,
   jsonb_build_object('class_id',p_class,'academic_year_id',p_year,
   'version',v_version,'item_count',v_rows));
 return jsonb_build_object('id',v_id,'version',v_version,
   'item_count',v_rows,'saved',true);
end;
$fn$;
create or replace function public.owner_save_class_fee_plan(
 p_school uuid,p_campus uuid,p_year uuid,p_class uuid,
 p_name text,p_items jsonb
) returns jsonb language sql security invoker set search_path=''
as $fn$ select app_private.owner_save_class_fee_plan(
 p_school,p_campus,p_year,p_class,p_name,p_items); $fn$;

revoke all on function app_private.owner_fee_setup_snapshot(uuid,uuid,uuid)
 from public,anon,authenticated;
revoke all on function public.owner_fee_setup_snapshot(uuid,uuid,uuid)
 from public,anon,authenticated;
revoke all on function app_private.owner_create_fee_category(uuid,text,text,text,boolean)
 from public,anon,authenticated;
revoke all on function public.owner_create_fee_category(uuid,text,text,text,boolean)
 from public,anon,authenticated;
revoke all on function app_private.owner_save_class_fee_plan(uuid,uuid,uuid,uuid,text,jsonb)
 from public,anon,authenticated;
revoke all on function public.owner_save_class_fee_plan(uuid,uuid,uuid,uuid,text,jsonb)
 from public,anon,authenticated;
grant execute on function app_private.owner_fee_setup_snapshot(uuid,uuid,uuid)
 to authenticated;
grant execute on function public.owner_fee_setup_snapshot(uuid,uuid,uuid)
 to authenticated;
grant execute on function app_private.owner_create_fee_category(uuid,text,text,text,boolean)
 to authenticated;
grant execute on function public.owner_create_fee_category(uuid,text,text,text,boolean)
 to authenticated;
grant execute on function app_private.owner_save_class_fee_plan(uuid,uuid,uuid,uuid,text,jsonb)
 to authenticated;
grant execute on function public.owner_save_class_fee_plan(uuid,uuid,uuid,uuid,text,jsonb)
 to authenticated;
